node -e '
// carve() for seed 7, depth 0, roughness 45 (copied from carve.js)
const seed=7, depth=0;
const start={x:1+(depth%2),y:2}, exit={x:4+((seed*7+depth*5)%9),y:2};
console.log("level0 start",start,"exit",exit);
// game ticks at k/30; pad right until 1/4 s, idle after; miner moves 1 cell per tick
const counts=[]; let x=start.x, depthCount=0;
for(let k=1;k<=9;k++){ const t=k/30; const right=t<0.25; if(right) x+=1; if(x===exit.x){depthCount++; counts.push([k,+t.toFixed(4),x]);} }
console.log("ticks on exit (k, t, x):",JSON.stringify(counts),"-> depth at t<=0.3 =",depthCount);
const r=(d)=>Math.round(d/10)/10; console.log("rock share roughness 45 vs 46:", r(45), r(46));
' 2>&1; ls /usr/bin/node 2>/dev/null || echo "node not on PATH"
